
var common = {
  visitWork: 'storeStaffWeb',
  now_lang: 'chinese',
  getAppDomain: function () {
    var reg = /app_domain=(.*?),/
    var arr = reg.exec(navigator.userAgent.toLowerCase())
    if (arr == null) {
      return ''
    } else {
      return arr[1]
    }
  },
  getVersion: function () {
    var reg = /pack_version=(.*?),/
    var arr = reg.exec(navigator.userAgent.toLowerCase())
    if (arr == null) {
      return '85'
    } else {
      return arr[1]
    }
  },
  getDeviceId: function () {
    var deviceId = common.getCache('device_id', true)
    if (deviceId) {
      console.log('device_id from cache', deviceId)
      return deviceId
    }
    if (common.checkApp()) {
      var reg = /device_id=(.*?),/
      var arr = reg.exec(navigator.userAgent.toLowerCase())
      if (arr == null) {
        return 'packapp'
      } else {
        return arr[1]
      }
    } else {
      return 'packapp'
    }
  },
  checkApp: function () {
    if (/(pigcms_pack_app)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },
  checkIos: function () {
    if (/(iphone|ipad|ipod)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },
  checkIosApp: function () {
    if (common.checkApp() && common.checkIos()) {
      return true
    } else {
      return false
    }
  },
  checkIphoneXApp: function () {
    if (common.checkIosApp() && window.innerHeight() == '812' && window.innerWidth() == '375') {
      return true
    } else {
      return false
    }
  },
  checkAndroid: function () {
    if (/(android)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },
  checkAndroidApp: function () {
    if (common.checkApp() && common.checkAndroid()) {
      return true
    } else {
      return false
    }
  },
  checkWeixin: function () {
    if (/(micromessenger)/.test(navigator.userAgent.toLowerCase())) {
      return true
    } else {
      return false
    }
  },
  getCache: function (key) {
    key = 'local_' + common.visitWork + '_' + key

    var string = localStorage.getItem(key)

    if (string) {
      if (string.substring(0, 5) == 'str||') {
        return string.substring(5)
      } else {
        return JSON.parse(string.substring(5))
      }
    }
  },
  setCache: function (key, obj) {
    key = 'local_' + common.visitWork + '_' + key

    var string = ''
    if (typeof (obj) == 'string') {
      string = 'str||' + obj
    } else {
      string = 'obj||' + JSON.stringify(obj)
    }
    return localStorage.setItem(key, string)
  },
  removeCache: function (key) {
    key = 'local_' + common.visitWork + '_' + key

    return localStorage.removeItem(key)
  },
  removeAllCache: function () {
    var storage = localStorage
    storage.clear()
  },
  iosFunction: function (paramStr, paramObj) {
    let packVersion = common.getVersion()
    let str = parseFloat(packVersion) >= 1000
    if (str == true) {
      window.webkit.messageHandlers.appJSBridgeMethod.postMessage(paramObj)
    } else {
      $('body').append('<iframe id="iosIframe" src="pigcmso2o://' + paramStr + '" style="display:none;"></iframe>')
    }
  }
}

export default common
