import Vue from 'vue'
import Router from 'vue-router'

Vue.use(Router)

const router = new Router({
  // mode: 'history',
  base: process.env.BASE_URL,
  routes: [
    {
      path: '/',
      name: 'vote_list',
      component: () => import('./pages/vote_list.vue'),
      meta: {
        title: '投票列表'
      }
    },
    {
      path: '/vote_list',
      name: 'vote_list',
      component: () => import('./pages/vote_list.vue'),
      meta: {
        title: '投票列表'
      }
    },
    {
      path: '/add_vote',
      name: 'add_vote',
      component: () => import('./pages/add_vote.vue'),
      meta: {
        title: '添加/编辑投票'
      }
    },
    {
      path: '/vote_statistics',
      name: 'vote_statistics',
      component: () => import('./pages/vote_statistics.vue'),
      meta: {
        title: '投票统计'
      }
    },
    {
      path: '/vote_join_detail',
      name: 'vote_join_detail',
      component: () => import('./pages/vote_join_detail.vue'),
      meta: {
        title: '投票详情'
      }
    }
  ]
})

// 全局路由守卫
router.beforeEach((to, from, next) => {
  console.log('navigation-guards', to, from);
  if (to.meta.title) {
    document.title = to.meta.title
  }
  next()
})

export default router
