import axios from 'axios'
import browser from '../common/browser'
import qs from 'qs'
import { Message, MessageBox } from 'element-ui'

// 创建 axios 实例
let http = axios.create({
  baseURL: process.env.VUE_APP_BASE_API,
  headers: {
    'Accept': 'application/json, text/javascript',
    'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8'
  },
  timeout: 60000
})

// 设置 post、put 默认 Content-Type
// http.defaults.headers.post['Content-Type'] = 'application/x-www-form-urlencoded; charset=UTF-8'
// http.defaults.headers.put['Content-Type'] = 'application/json'

// 添加请求拦截器
http.interceptors.request.use(config => {
  if (config.method === 'post') {
    // post、put 提交时，将对象转换为string, 为处理后台解析问题
    config.data = config.data instanceof FormData ? config.data : qs.stringify(config.data)
  } else if (config.method === 'get' && browser.isIE) {
    // 给GET 请求后追加时间戳， 解决IE GET 请求缓存问题
    let symbol = config.url.indexOf('?') >= 0 ? '&' : '?'
    config.url += symbol + '_=' + Date.now()
  }

  // 请求发送前进行处理
  return config
}, error => {
  // 请求错误处理
  return Promise.reject(error)
})

// 添加响应拦截器
http.interceptors.response.use(response => {
  let { data } = response
  if (data.errorCode === 0) {
    return data.result
  } else if (data.errorCode === 1) {
    return false
  } else if (data.errorCode === 10001) {
    MessageBox.confirm(data.errorMsg, '提示', {
      confirmButtonText: '确定',
      cancelButtonText: '取消',
      type: 'warning'
    }).then(() => {
      // on confirm
      window.location.href = data.result.redirect
    }).catch(() => {})
  } else if (data.errorMsg) {
    Message.error({
      type: 'success',
      message: data.errorMsg
    })
    return false
  }
}, error => {
  let info = {}
  let { status, statusText, data } = error.response
  if (!error.response) {
    info = {
      code: 5000,
      msg: 'Network Error'
    }
  } else {
    // 此处整理错误信息格式
    info = {
      code: status,
      data: data,
      msg: statusText
    }
  }
  return Promise.reject(info)
})

/**
 * 创建统一封装过的 axios 实例
 * @return {AxiosInstance}
 */
export default function () {
  return http
}
